TESIS_PDF = [
    {"codigo": "C24-201", "titulo": "Sistema de Gestión de Residuos con Geolocalización", "autores": "M. Huamán · J. Ticona · L. Rivas", "grupo": "Grupo Alpha", "promocion": "C24", "estado": "Aprobada", "score": "88/100", "tecnologias": ["React", "Node.js", "PostgreSQL", "Google Maps API"], "resumen": "Sistema web georreferenciado para optimizar rutas de recolección de residuos sólidos municipales. Implementa el algoritmo Clarke-Wright para planificación óptima de rutas. Los ciudadanos reportan puntos de acumulación irregular vía app móvil integrada.", "secciones": {"Introducción": "Lima genera 9,000 toneladas de residuos diariamente pero el 30% no recibe recolección adecuada. Las rutas actuales son fijas e ineficientes. Este proyecto implementa un sistema de optimización dinámica de rutas de recolección basado en datos geoespaciales en tiempo real.", "Marco Teórico": "El VRP (Vehicle Routing Problem) es un problema NP-hard resuelto con heurísticas como Clarke-Wright. PostgreSQL con PostGIS permite almacenamiento y consulta geoespacial eficiente. La API Google Maps provee geocodificación y matrices de distancia/tiempo.", "Metodología": "Se levantaron datos de generación de residuos de 5 distritos durante 3 meses. El algoritmo Clarke-Wright genera rutas semanales optimizadas. Una app para choferes muestra la ruta GPS con desvíos automáticos por tráfico usando datos de Google Traffic API.", "Resultados": "Las rutas optimizadas redujeron el consumo de combustible en 28%. El tiempo de recolección por tonelada disminuyó 22%. La cobertura de recolección aumentó del 71% al 89% con la misma flota vehicular.", "Conclusiones": "El sistema generó ahorros significativos en operación. Se recomienda incorporar sensores de nivel de llenado en contenedores para optimización dinámica en tiempo real, eliminando la planificación semanal estática."}},
    {"codigo": "C24-202", "titulo": "Reconocimiento Facial para Control de Asistencia con Python", "autores": "D. Tapia · R. Gutiérrez", "grupo": "Grupo Beta", "promocion": "C24", "estado": "Aprobada", "score": "92/100", "tecnologias": ["Python", "OpenCV", "FaceNet", "Django", "React"], "resumen": "Sistema de control de asistencia basado en reconocimiento facial con FaceNet. Procesa video en tiempo real desde cámara IP, registra entradas y salidas automáticamente con 99.1% de precisión. Tolerante a variaciones de iluminación y uso parcial de mascarillas.", "secciones": {"Introducción": "El buddy punching genera pérdidas de 4.5% de horas laborales. Los sistemas de tarjeta RFID son fácilmente burlados. La biometría facial elimina este problema al verificar la identidad física. Este proyecto implementa un sistema robusto adaptado al entorno corporativo.", "Marco Teórico": "FaceNet genera embeddings de 128 dimensiones para representar rostros. La similitud del coseno entre embeddings determina si dos imágenes corresponden a la misma persona. MTCNN detecta y alinea rostros en tiempo real con alta precisión.", "Metodología": "Se registraron 10 fotos de 150 empleados en distintas condiciones. FaceNet genera embeddings almacenados en PostgreSQL. Una cámara IP Hikvision captura video 720p. Por cada frame se detectan rostros y comparan contra la base de embeddings en menos de 0.8s.", "Resultados": "Precisión del 99.1% en condiciones normales. Tasa de falsos positivos del 0.07%. Con mascarilla N95 la precisión bajó al 87.3% usando región ocular. El sistema fue adoptado en 3 empresas del sector retail durante el piloto.", "Conclusiones": "Sistema efectivo para control de asistencia. Se recomienda implementar detección de vitalidad (liveness detection) para prevenir ataques con fotografías impresas o videos reproducidos."}},
    {"codigo": "C24-203", "titulo": "Chatbot Médico con Triaje Inteligente usando GPT-4", "autores": "S. Ccasa · V. Mamani · A. Torres", "grupo": "Grupo Gamma", "promocion": "C24", "estado": "Aprobada", "score": "95/100", "tecnologias": ["Python", "LangChain", "OpenAI GPT-4", "FastAPI", "React"], "resumen": "Chatbot de triaje médico que evalúa síntomas mediante conversación natural y recomienda el nivel de urgencia de atención. Usa GPT-4 con base de conocimiento médico vectorial indexada con embeddings. Incluye escalación automática a médico de guardia para casos críticos.", "secciones": {"Introducción": "El 60% de emergencias hospitalarias en Lima son casos que podrían resolverse ambulatoriamente, saturando los recursos. El triaje manual es inconsistente. Este proyecto implementa un asistente IA de triaje 24/7 basado en el protocolo Manchester.", "Marco Teórico": "GPT-4 posee conocimiento médico generalista capaz de evaluaciones de síntomas coherentes. LangChain facilita la construcción de chains con LLMs incluyendo RAG y memoria de conversación. ChromaDB indexa los embeddings de 500 fichas clínicas para recuperación semántica.", "Metodología": "Se diseñó un prompt system que instruye a GPT-4 a seguir el protocolo Manchester (MTS). La base de conocimiento fue indexada con Ada-002. LangChain implementa RAG para fundamentar evaluaciones en casos clínicos. 3 médicos de emergencia validaron 100 casos simulados.", "Resultados": "Concordancia del 86% con el triaje médico. En 98% de casos el chatbot fue conservador. Tiempo promedio de triaje: 4.2 minutos. Médicos calificaron las recomendaciones como adecuadas o conservadoras en 96% de casos.", "Conclusiones": "Desempeño clínicamente aceptable que puede complementar el proceso de admisión. La tendencia conservadora es deseable en contextos médicos. Se recomienda estudio prospectivo en condiciones reales con supervisión médica previa a implementación clínica."}},
    {"codigo": "C24-204", "titulo": "Predicción de Demanda para Retail con LSTM y Prophet", "autores": "K. Lazo · E. Condori", "grupo": "Grupo Delta", "promocion": "C24", "estado": "Aprobada", "score": "90/100", "tecnologias": ["Python", "TensorFlow", "Prophet", "Tableau", "PostgreSQL"], "resumen": "Sistema de predicción de demanda de productos para supermercado que combina Prophet y LSTM en un modelo ensemble. Predicciones a 30 días con MAPE del 8.3% que reducen sobrestock 31% y quiebres de inventario 44%. Dashboard Tableau por categoría y sucursal.", "secciones": {"Introducción": "El sobrestock inmoviliza el 8% del capital de trabajo y los quiebres generan pérdidas del 4% de ventas. Los modelos ARIMA tradicionales no capturan efectos de promociones. Este proyecto implementa predicción avanzada con ensemble de modelos estadísticos y deep learning.", "Marco Teórico": "Prophet descompone series temporales en tendencia, estacionalidad y efectos de festivos. LSTM captura dependencias temporales de largo alcance en series multivariadas. El ensemble pondera ambos modelos según desempeño histórico por categoría de producto.", "Metodología": "Se usaron 3 años de datos diarios de 2,400 SKUs. Prophet modela estacionalidad más 47 festivos peruanos. LSTM recibe el pronóstico Prophet más variables exógenas (precio, promociones, temperatura). El ensemble promedia ponderadamente los dos modelos por categoría.", "Resultados": "MAPE del 8.3% vs 14.7% del método anterior. Sobrestock reducido 31% y quiebres reducidos 44% en 3 meses. Ahorro estimado de S/. 1.2 millones anuales en capital de trabajo para la cadena piloto de 12 supermercados.", "Conclusiones": "El ensemble Prophet-LSTM superó los métodos estadísticos tradicionales. El impacto económico validado justifica la inversión. Se recomienda incorporar datos de eventos externos (deportivos, climáticos) para refinar predicciones de picos de demanda."}},
    {"codigo": "C24-205", "titulo": "Tutoría Virtual de Matemáticas con IA Generativa y NextJS", "autores": "P. Aliaga · N. Chávez · M. Quispe", "grupo": "Grupo Sigma", "promocion": "C24", "estado": "En Revisión", "score": "", "tecnologias": ["NextJS", "Python", "Google Gemini", "PostgreSQL", "KaTeX"], "resumen": "Tutor virtual de matemáticas que resuelve problemas paso a paso usando Gemini 2.5 Pro. Renderiza ecuaciones LaTeX en tiempo real, detecta el punto de confusión del estudiante y adapta el nivel de explicación. Incluye generador de ejercicios personalizados de dificultad progresiva.", "secciones": {"Introducción": "Solo el 15% de estudiantes secundarios peruanos alcanzan nivel satisfactorio en matemáticas (PISA 2023). Las tutorías privadas son inaccesibles económicamente. Los LLMs han demostrado capacidad matemática comparable a tutores humanos en benchmarks estandarizados.", "Marco Teórico": "Gemini 2.5 Pro posee capacidades nativas de razonamiento matemático y generación LaTeX. Chain-of-thought prompting mejora la precisión al forzar mostrar el razonamiento paso a paso. KaTeX renderiza fórmulas matemáticas en navegadores con alta velocidad.", "Metodología": "Next.js 14 con App Router para SSR optimizado. El componente de chat envía el problema a una API Python que construye el prompt pedagógico. Gemini responde con solución en LaTeX que KaTeX renderiza en tiempo real. Un módulo generador crea ejercicios similares de dificultad progresiva.", "Resultados": "En pruebas con 45 estudiantes de secundaria durante 6 semanas, el grupo con tutor IA mejoró 2.8 puntos promedio (de 11.3 a 14.1 sobre 20). El 91% prefirió el tutor IA sobre videos tutoriales de YouTube.", "Conclusiones": "Herramienta pedagógica efectiva con impacto medible. La adaptación del nivel de explicación fue el factor más valorado. Se recomienda desarrollar módulos para física y química como extensión natural del sistema."}},
    {"codigo": "C24-206", "titulo": "Automatización RPA para Facturación Electrónica SUNAT", "autores": "C. Apaza · R. Lira", "grupo": "Grupo Omega", "promocion": "C24", "estado": "Aprobada", "score": "86/100", "tecnologias": ["Python", "UiPath", "SAP", "PostgreSQL", "REST API SUNAT"], "resumen": "Robot RPA que extrae facturas de SAP, las formatea según UBL 2.1 de SUNAT, las envía vía API al OSE y registra los CDR. Reduce el tiempo de facturación de 8 minutos a 23 segundos por comprobante con tasa de éxito del 99.6%.", "secciones": {"Introducción": "La facturación electrónica obligatoria involucra 14 pasos manuales entre SAP y SUNAT. Este proceso repetitivo genera errores y consume tiempo valioso del equipo contable. La automatización RPA elimina la intervención humana en el ciclo completo.", "Marco Teórico": "RPA replica acciones humanas en interfaces de usuario sin modificar los sistemas existentes. UiPath es la plataforma líder de RPA con soporte nativo para SAP. El formato UBL 2.1 XML con firma digital X.509 es el estándar SUNAT para comprobantes electrónicos.", "Metodología": "Robot UiPath monitorea la cola de facturas SAP cada 5 minutos. Por cada factura: extrae datos, mapea a XML UBL 2.1, aplica firma digital y envía al OSE via API REST. El CDR se almacena en PostgreSQL vinculado al registro SAP. Manejo de excepciones con notificación al equipo contable.", "Resultados": "12,847 facturas procesadas en el primer mes con 99.6% de éxito. Tiempo por comprobante reducido de 8 minutos a 23 segundos. El equipo de facturación (4 personas) reasignado a tareas de mayor valor. Ahorro mensual estimado en S/. 8,400.", "Conclusiones": "La automatización RPA demostró ser la implementación de mayor ROI del portafolio. La tasa de éxito 99.6% supera el desempeño manual 97.2%. Se recomienda extender a notas de crédito/débito y conciliación contable automática."}},
    {"codigo": "C24-207", "titulo": "Crowdfunding para Innovación Social con Blockchain Polygon", "autores": "T. Villanueva · B. Quispe · J. Zegarra", "grupo": "Grupo Alpha", "promocion": "C24", "estado": "Aprobada", "score": "93/100", "tecnologias": ["React", "Solidity", "Web3.js", "IPFS", "Node.js"], "resumen": "Plataforma descentralizada de crowdfunding en Polygon para proyectos de impacto social. Contratos inteligentes Solidity gestionan recaudación y distribución de fondos de manera transparente. Los documentos se almacenan en IPFS para garantizar inmutabilidad.", "secciones": {"Introducción": "El financiamiento de proyectos sociales enfrenta desconfianza por la opacidad en el uso de fondos. Las plataformas centralizadas cobran 5-10% de comisión. Blockchain ofrece transparencia total y eliminación de intermediarios para financiamiento colectivo.", "Marco Teórico": "Polygon es una solución de capa 2 para Ethereum con transacciones rápidas y comisiones mínimas. Los Smart Contracts en Solidity ejecutan automáticamente las condiciones de financiamiento. IPFS almacena documentos de forma descentralizada e inmutable.", "Metodología": "Contratos Solidity con lógica de: creación de campaña, metas intermedias, votación de donantes para liberar fondos y reembolso automático si no se alcanza la meta. Frontend React con Web3.js para interactuar con MetaMask. Auditoría de seguridad con Slither y MythX.", "Resultados": "12 campañas piloto recaudaron 45,000 MATIC (S/. 168,000). Tasa de cumplimiento del 83%. Comisiones del 2% vs 8% de la industria. 100% de donantes pudo verificar el uso de fondos en el explorador de blockchain.", "Conclusiones": "La trazabilidad en blockchain fue el factor diferenciador más valorado. Se recomienda desarrollar un sistema de reputación on-chain y simplificar el onboarding de donantes sin experiencia previa en criptomonedas."}},
    {"codigo": "C24-208", "titulo": "Dron Autónomo de Inspección Industrial con ROS2 y YOLO", "autores": "A. Huanca · F. Quispe", "grupo": "Grupo Beta", "promocion": "C24", "estado": "Observada", "score": "", "tecnologias": ["Python", "ROS2", "OpenCV", "ArduPilot", "YOLOv8"], "resumen": "Sistema de navegación autónoma para dron de inspección de infraestructura industrial. Usa ROS2 para gestión de misiones, YOLOv8 para detección de anomalías (corrosión, grietas, fugas) y telemetría en tiempo real al centro de control. Reduce el tiempo de inspección de 6 horas a 12 minutos.", "secciones": {"Introducción": "La inspección manual en altura genera riesgos graves y costos elevados por montaje de andamios. Los drones comerciales cuestan US$ 15,000-50,000 por misión. Este proyecto desarrolla una solución open-source de bajo costo para inspección autónoma de infraestructura industrial.", "Marco Teórico": "ROS2 proporciona comunicación inter-procesos para sistemas robóticos basada en DDS. ArduPilot es el firmware open-source más usado en UAVs con soporte para misiones autónomas. YOLOv8 detecta objetos en tiempo real en una sola pasada por la red neuronal. MAVLink es el protocolo estándar de telemetría dron-estación.", "Metodología": "Hexacóptero con Pixhawk 6C y cámara gimbal Sony ZV-E10. YOLOv8 fine-tuneado para 6 tipos de anomalías industriales. 45 misiones de prueba en planta petroquímica piloto. Imágenes de alta resolución transmitidas por WiFi 5GHz a la estación base.", "Resultados": "91.1% de misiones completadas autónomamente. YOLOv8 con 84.7% de precisión y 91.3% de recall en detección de anomalías. Inspección de tanque de 20m: 12 minutos vs 6 horas manual. Se detectaron 3 focos de corrosión no identificados previamente.", "Conclusiones": "Alternativa viable y económica para inspección industrial. Limitaciones: sensibilidad a interferencias RF y condiciones climáticas adversas. Se recomienda mejorar robustez en interiores con SLAM y explorar HoloLens para liberar las manos del técnico."}},
    {"codigo": "C24-209", "titulo": "Gestión de Talento con Análisis Predictivo de Rotación", "autores": "L. Quispe · C. Mamani · V. Ramos", "grupo": "Grupo Gamma", "promocion": "C24", "estado": "Aprobada", "score": "87/100", "tecnologias": ["Django", "React", "Power BI", "Scikit-learn", "PostgreSQL"], "resumen": "Sistema de RRHH con módulo predictivo de riesgo de rotación de empleados usando Random Forest. Identifica colaboradores en riesgo 3 meses antes de posible renuncia con AUC-ROC de 0.87. Dashboard Power BI integrado para visualización ejecutiva.", "secciones": {"Introducción": "El costo de reemplazar un empleado equivale al 50-200% de su salario anual. La tasa de rotación en empresas tech peruanas es del 23% anual. Los departamentos de RRHH reaccionan a renuncias sin herramientas predictivas. Este proyecto implementa gestión proactiva del talento.", "Marco Teórico": "Random Forest combina múltiples árboles de decisión para mejorar precisión y reducir overfitting. Variables predictoras incluyen: satisfacción laboral, desempeño, compensación relativa al mercado y distancia al trabajo. La importancia de características identifica los factores más influyentes en la rotación.", "Metodología": "Dataset de 850 empleados de 5 empresas durante 3 años con 28 variables. Random Forest entrenado con 70% y validado con estratificación. El modelo genera puntuación de riesgo 0-100. Umbrales de 70+ desencadenan alertas al gerente de RRHH con recomendaciones de intervención.", "Resultados": "AUC-ROC de 0.87 en conjunto de prueba. Predijo correctamente el 76% de renuncias con 3 meses de anticipación. Intervenciones en 43 empleados de alto riesgo retuvieron al 67%. Dashboard Power BI adoptado por 100% de gerentes de RRHH.", "Conclusiones": "El sistema predictivo demostró valor estratégico medible para gestión del talento. La identificación temprana permite intervenciones exitosas. Se recomienda incorporar análisis de sentimiento de comunicaciones internas (con consentimiento) para mejorar la precisión."}},
    {"codigo": "C24-210", "titulo": "Clasificación Automática de Residuos con IA y Raspberry Pi", "autores": "J. Llanos · S. Condori", "grupo": "Grupo Delta", "promocion": "C24", "estado": "Aprobada", "score": "91/100", "tecnologias": ["Python", "TensorFlow Lite", "Raspberry Pi", "OpenCV", "React"], "resumen": "Contenedor inteligente con brazo robótico que clasifica automáticamente residuos en 5 categorías usando MobileNetV2 optimizado para TFLite. Procesa la imagen en menos de 500ms con 93.4% de precisión. Motorizó un aumento del 340% en la tasa de reciclaje en edificios piloto.", "secciones": {"Introducción": "El reciclaje efectivo en Perú alcanza apenas el 1.9% de los residuos generados. La clasificación deficiente en origen es la principal barrera. Un contenedor inteligente que clasifica automáticamente reduce la fricción del usuario y mejora la calidad del material reciclado.", "Marco Teórico": "MobileNetV2 es una CNN optimizada para edge computing en dispositivos ARM. TFLite convierte modelos TensorFlow al formato optimizado para microcontroladores. La cuantización de 8 bits reduce el tamaño del modelo en 75% con mínima pérdida de precisión.", "Metodología": "Dataset de 15,000 imágenes de residuos (3,000 por clase). MobileNetV2 fine-tuneado con data augmentation durante 30 épocas. Ejecuta en Raspberry Pi 4 con acelerador USB Coral Edge TPU. Brazo de 5 servomotores dirige el residuo al compartimento correspondiente en menos de 500ms.", "Resultados": "Precisión promedio del 93.4%: orgánico 96%, plástico 94%, papel 91%, vidrio 95%, metal 92%. 4,872 residuos clasificados en 2 edificios piloto durante 2 meses. La tasa de reciclaje aumentó 340% respecto a contenedores tradicionales.", "Conclusiones": "La automatización de clasificación de residuos es técnicamente viable y produce impacto medible. La precisión del 93.4% supera el umbral de practicidad para implementación a escala. Se recomienda desarrollar modelo de franquicia para despliegue masivo en condominios y centros comerciales."}},
]

def crear_pdf(tesis, ruta):
    doc = SimpleDocTemplate(ruta, pagesize=A4, rightMargin=2*cm, leftMargin=2.5*cm, topMargin=2.5*cm, bottomMargin=2*cm)
    styles = getSampleStyleSheet()
    titulo_style = ParagraphStyle('T', parent=styles['Title'], fontSize=15, leading=20, spaceAfter=6, alignment=TA_CENTER, textColor=colors.HexColor('#1e293b'))
    meta_style = ParagraphStyle('M', parent=styles['Normal'], fontSize=10, leading=14, alignment=TA_CENTER, textColor=colors.HexColor('#64748b'), spaceAfter=4)
    section_style = ParagraphStyle('S', parent=styles['Heading2'], fontSize=12, leading=16, spaceBefore=14, spaceAfter=6, textColor=colors.HexColor('#4f46e5'))
    body_style = ParagraphStyle('B', parent=styles['Normal'], fontSize=10, leading=15, alignment=TA_JUSTIFY, textColor=colors.HexColor('#334155'), spaceAfter=8)
    story = []
    story.append(Paragraph("TECSUP — Departamento de Tecnología Digital", meta_style))
    story.append(Paragraph(f"Proyecto de Tesis — Promoción {tesis['promocion']}", meta_style))
    story.append(Spacer(1, 0.4*cm))
    story.append(HRFlowable(width="100%", thickness=2, color=colors.HexColor('#4f46e5')))
    story.append(Spacer(1, 0.5*cm))
    story.append(Paragraph(tesis['titulo'], titulo_style))
    story.append(Spacer(1, 0.4*cm))
    score_str = tesis['score'] if tesis['score'] else "Por evaluar"
    meta_data = [["Autores:", tesis['autores']], ["Grupo:", tesis['grupo']], ["Código:", tesis['codigo']], ["Estado:", tesis['estado']], ["Calificación:", score_str], ["Tecnologías:", " · ".join(tesis['tecnologias'])]]
    mt = Table(meta_data, colWidths=[3*cm, 13*cm])
    mt.setStyle(TableStyle([('FONT',(0,0),(0,-1),'Helvetica-Bold'),('FONT',(1,0),(1,-1),'Helvetica'),('FONTSIZE',(0,0),(-1,-1),9),('TEXTCOLOR',(0,0),(0,-1),colors.HexColor('#4f46e5')),('TEXTCOLOR',(1,0),(1,-1),colors.HexColor('#334155')),('ROWBACKGROUNDS',(0,0),(-1,-1),[colors.HexColor('#f8fafc'),colors.white]),('BOTTOMPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('LEFTPADDING',(0,0),(-1,-1),6)]))
    story.append(mt)
    story.append(Spacer(1, 0.5*cm))
    story.append(HRFlowable(width="100%", thickness=1, color=colors.HexColor('#e2e8f0')))
    story.append(Paragraph("Resumen", section_style))
    story.append(Paragraph(tesis['resumen'], body_style))
    for titulo_sec, contenido in tesis['secciones'].items():
        story.append(Paragraph(titulo_sec, section_style))
        story.append(Paragraph(contenido, body_style))
    story.append(Spacer(1, 0.5*cm))
    story.append(HRFlowable(width="100%", thickness=1, color=colors.HexColor('#e2e8f0')))
    story.append(Spacer(1, 0.3*cm))
    story.append(Paragraph(f"Repositorio DDS TECSUP · Código: {tesis['codigo']} · TecSis-IA", meta_style))
    doc.build(story)

for t in TESIS_PDF:
    nombre = f"{t['codigo'].replace('-','_')}_{t['titulo'][:30].replace(' ','_').replace('/','_').replace(':','')}.pdf"
    ruta = os.path.join(BASE, nombre)
    crear_pdf(t, ruta)
    print(f"  OK: {nombre}")

print(f"\nGenerados {len(TESIS_PDF)} PDFs en {BASE}")
